const appointment = $json.data;

if (!appointment?.id) {
  throw new Error(
    'Directus no devolvió una cita válida'
  );
}

function contactLabel(contact) {
  if (!contact) {
    return 'Sin contacto';
  }

  const name = [
    contact.first_name,
    contact.last_name
  ]
    .filter(Boolean)
    .join(' ')
    .trim();

  if (contact.company && name) {
    return `${contact.company} · ${name}`;
  }

  return (
    contact.company ||
    name ||
    'Sin contacto'
  );
}

const contact = appointment.contact_id;

return [
  {
    json: {
      status: 'resolved',

      appointment: {
        id:
          appointment.id,

        title:
          appointment.title ?? null,

        start_at:
          appointment.start_at ?? null,

        end_at:
          appointment.end_at ?? null,

        status:
          appointment.status ?? null,

        notes:
          appointment.notes ?? null,

        source:
          appointment.source ?? null,

        external_provider:
          appointment.external_provider ?? null,

        external_event_id:
          appointment.external_event_id ?? null,

        created_at:
          appointment.created_at ?? null,

        updated_at:
          appointment.updated_at ?? null
      },

      contact: contact
        ? {
            id:
              contact.id,

            first_name:
              contact.first_name ?? null,

            last_name:
              contact.last_name ?? null,

            company:
              contact.company ?? null,

            email:
              contact.email ?? null,

            status:
              contact.status ?? null,

            label:
              contactLabel(contact)
          }
        : null
    }
  }
];

const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const appointmentId = clean(
  input.appointment_id
);

if (!appointmentId) {
  throw new Error(
    'appointment_id es obligatorio'
  );
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(appointmentId)) {
  throw new Error(
    `appointment_id no es un UUID válido: ${appointmentId}`
  );
}

return [
  {
    json: {
      appointment_id: appointmentId
    }
  }
];
